// Android input + matchmaking shim for shankpit-460.
//
// sp-host.js is generated by `parena build` and must not be hand-edited, so this
// file touches none of it. Instead it does two things the generated host already
// knows how to read:
//
//   1. Virtual gamepad. The wasm takes a standard gamepad (sp_pad) and the host
//      polls navigator.getGamepads() every frame, so overriding getGamepads()
//      with a synthetic pad gives us a full touch control scheme -- two sticks
//      and six buttons -- without patching the game or the host. This is the
//      same input path a physical controller uses, which is why it needs no
//      pointer-lock (unavailable in Android WebView) to aim.
//
//   2. Matchmaking. The web build talks to /api/v1/shankpit460/* on its own
//      origin. With a backend configured we rewrite those calls to it. With no
//      backend (the current default) we install an inert WebSocket so the game
//      drops straight into the local bot match instead of retrying a dead
//      endpoint every 8 seconds -- the wasm already runs a full bot match
//      while it searches, so "no matchmaking" degrades to the demo, not an error.
(function () {
  'use strict';

  var params = new URLSearchParams(window.location.search || '');
  var backend = (params.get('backend') || window.SHANKPIT_BACKEND || '').replace(/\/+$/, '');
  var offline = backend === '';

  var doc = document;
  var byId = function (id) { return doc.getElementById(id); };

  // ---------------------------------------------------------------- matchmaking
  var RealWebSocket = window.WebSocket;

  function offlineSocket() {
    // readyState 3 (CLOSED) is all the host checks before it tries to send, and
    // because this object is never null the host never reconnects. No events are
    // dispatched, so the wasm keeps its own bot match running.
    this.readyState = 3;
    this.binaryType = 'arraybuffer';
    this.url = '';
  }
  offlineSocket.prototype.addEventListener = function () {};
  offlineSocket.prototype.removeEventListener = function () {};
  offlineSocket.prototype.send = function () {};
  offlineSocket.prototype.close = function () {};

  function withBackend(url) {
    var u = String(url);
    if (u.charAt(0) !== '/') return u;
    var http = backend;
    return http.replace(/^http/, 'ws') + u;
  }

  function BackendSocket(url, protocols) {
    return protocols === undefined
      ? new RealWebSocket(withBackend(url))
      : new RealWebSocket(withBackend(url), protocols);
  }
  BackendSocket.prototype = RealWebSocket.prototype;
  ['CONNECTING', 'OPEN', 'CLOSING', 'CLOSED'].forEach(function (k) {
    if (typeof RealWebSocket[k] === 'number') BackendSocket[k] = RealWebSocket[k];
  });

  if (offline) {
    window.WebSocket = offlineSocket;
  } else {
    window.WebSocket = BackendSocket;
    var realFetch = window.fetch.bind(window);
    window.fetch = function (input, init) {
      if (typeof input === 'string' && input.charAt(0) === '/') {
        return realFetch(backend + input, init);
      }
      return realFetch(input, init);
    };
  }

  // The generated host paints its own status pill from wasm state; while offline
  // "Searching for a match" is true but misleading, so reword it in place.
  function watchStatus() {
    var pill = byId('sp-pill');
    if (!pill || offline === false) return;
    var reword = function () {
      if (pill.textContent === 'Searching for a match') {
        pill.textContent = 'Bot match (no matchmaking)';
      }
    };
    if (window.MutationObserver) {
      new window.MutationObserver(reword).observe(pill, { childList: true, characterData: true, subtree: true });
    }
    reword();
    var chip = byId('sp-offline');
    if (chip) chip.hidden = false;
  }

  // ------------------------------------------------------------------- gamepad
  // Standard mapping: 0 A, 1 B, 2 X, 3 Y, 4 LB, 5 RB, 6 LT, 7 RT.
  var BTN = { JUMP: 0, CROUCH: 1, RELOAD: 2, ABILITY: 6, FIRE: 7, NEXT: 5 };

  var pad = {
    axes: [0, 0, 0, 0],
    buttons: [],
    connected: true,
    index: 0,
    id: 'shankpit-460 touch',
    mapping: 'standard',
    timestamp: 0
  };
  for (var i = 0; i < 16; i++) pad.buttons.push({ pressed: false, value: 0 });

  function press(btn) {
    var b = pad.buttons[btn];
    if (!b) return;
    b.pressed = true;
    b.value = 1;
  }
  function release(btn) {
    var b = pad.buttons[btn];
    if (!b) return;
    b.pressed = false;
    b.value = 0;
  }
  function releaseAll() {
    for (var n = 0; n < pad.buttons.length; n++) release(n);
    pad.axes[0] = pad.axes[1] = pad.axes[2] = pad.axes[3] = 0;
    setKnob(0, 0);
  }

  function getGamepads() {
    return [pad, null, null, null];
  }
  if (navigator.getGamepads) {
    navigator.getGamepads = getGamepads;
  } else if (navigator.webkitGetGamepads) {
    navigator.webkitGetGamepads = getGamepads;
  } else {
    try { navigator.getGamepads = getGamepads; } catch (e) { /* read-only in old engines */ }
  }

  // ---------------------------------------------------------------------- touch
  var LOOK_GAIN = 1 / 55;   // px of drag -> stick deflection
  var LOOK_DECAY = 14;      // per second; keeps a short flick moving briefly
  var DEADZONE = 0.14;

  var stick = byId('sp-stick');
  var knob = byId('sp-knob');
  var canvas = byId('sp-canvas');
  var stage = byId('sp-stage');
  var started = false;

  function setKnob(dx, dy) {
    if (!knob) return;
    knob.style.transform = 'translate(' + dx.toFixed(1) + 'px,' + dy.toFixed(1) + 'px)';
  }

  function shape(v) {
    return Math.abs(v) < DEADZONE ? 0 : v;
  }

  function startOnce() {
    if (started) return;
    started = true;
    // Unlock audio and satisfy any click-to-start: the host's mousedown handler
    // is what builds the AudioContext, and a pad button is what leaves the title.
    try {
      if (canvas) {
        var r = canvas.getBoundingClientRect();
        var opts = { bubbles: true, cancelable: true, button: 0, clientX: r.left + r.width / 2, clientY: r.top + r.height / 2 };
        canvas.dispatchEvent(new MouseEvent('mousedown', opts));
        canvas.dispatchEvent(new MouseEvent('mouseup', opts));
      }
    } catch (e) { /* pointer lock is unavailable in WebView; the pad path needs none */ }
    press(BTN.JUMP);
    window.setTimeout(function () { release(BTN.JUMP); }, 120);
  }

  // --- left stick ---
  var stickId = null;
  function stickMove(e) {
    if (!stick) return;
    var r = stick.getBoundingClientRect();
    var cx = r.left + r.width / 2;
    var cy = r.top + r.height / 2;
    var lim = r.width / 2;
    var dx = e.clientX - cx;
    var dy = e.clientY - cy;
    var len = Math.sqrt(dx * dx + dy * dy);
    if (len > lim) { dx *= lim / len; dy *= lim / len; }
    setKnob(dx, dy);
    pad.axes[0] = shape(dx / lim);
    pad.axes[1] = shape(dy / lim);
  }
  if (stick) {
    stick.addEventListener('pointerdown', function (e) {
      stickId = e.pointerId;
      try { stick.setPointerCapture(e.pointerId); } catch (err) {}
      setKnob(0, 0);
      pad.axes[0] = pad.axes[1] = 0;
      startOnce();
      e.preventDefault();
    });
    stick.addEventListener('pointermove', function (e) {
      if (stickId !== e.pointerId) return;
      stickMove(e);
      e.preventDefault();
    });
    var stickEnd = function (e) {
      if (stickId !== e.pointerId) return;
      stickId = null;
      pad.axes[0] = pad.axes[1] = 0;
      setKnob(0, 0);
    };
    stick.addEventListener('pointerup', stickEnd);
    stick.addEventListener('pointercancel', stickEnd);
  }

  // --- drag-to-aim: dragging anywhere outside the controls ---
  var lookId = null;
  var lookX = 0, lookY = 0;

  function aimFromDrag(e) {
    pad.axes[2] = Math.max(-1, Math.min(1, lookX * LOOK_GAIN));
    pad.axes[3] = Math.max(-1, Math.min(1, lookY * LOOK_GAIN));
    lookX = 0;
    lookY = 0;
  }

  if (stage) {
    stage.addEventListener('pointerdown', function (e) {
      if (lookId !== null) return;
      lookId = e.pointerId;
      lookX = lookY = 0;
      startOnce();
    });
    stage.addEventListener('pointermove', function (e) {
      if (lookId !== e.pointerId) return;
      lookX += e.movementX || 0;
      lookY += e.movementY || 0;
      if (!e.movementX && !e.movementY) {
        // movementX is unreliable for touch; fall back to movement since last point
        if (e.__lx !== undefined) { lookX += e.clientX - e.__lx; lookY += e.clientY - e.__ly; }
        e.__lx = e.clientX; e.__ly = e.clientY;
      }
      aimFromDrag(e);
    });
    var lookEnd = function (e) {
      if (lookId !== e.pointerId) return;
      lookId = null;
      lookX = lookY = 0;
    };
    stage.addEventListener('pointerup', lookEnd);
    stage.addEventListener('pointercancel', lookEnd);
  }

  // --- action buttons ---
  var held = {};
  var btns = doc.querySelectorAll ? doc.querySelectorAll('#sp-buttons .btn') : [];
  for (var b = 0; b < btns.length; b++) {
    (function (el) {
      var idx = parseInt(el.getAttribute('data-btn'), 10);
      var down = function (e) {
        held[e.pointerId] = idx;
        try { el.setPointerCapture(e.pointerId); } catch (err) {}
        el.classList.add('on');
        press(idx);
        startOnce();
        e.preventDefault();
      };
      var up = function (e) {
        if (held[e.pointerId] !== idx) return;
        delete held[e.pointerId];
        el.classList.remove('on');
        release(idx);
        e.preventDefault();
      };
      el.addEventListener('pointerdown', down);
      el.addEventListener('pointerup', up);
      el.addEventListener('pointercancel', up);
      el.addEventListener('pointerleave', function (e) {
        if (e.buttons === 0) return;
        up(e);
      });
    })(btns[b]);
  }

  // --- per-frame decay of the aim axes + stuck-input cleanup ---
  var last = 0;
  function frame(t) {
    var dt = last ? Math.min(0.1, (t - last) / 1000) : 0;
    last = t;
    if (lookId === null) {
      var k = Math.exp(-LOOK_DECAY * dt);
      pad.axes[2] *= k;
      pad.axes[3] *= k;
      if (Math.abs(pad.axes[2]) < 0.01) pad.axes[2] = 0;
      if (Math.abs(pad.axes[3]) < 0.01) pad.axes[3] = 0;
    }
    window.requestAnimationFrame(frame);
  }

  if (doc.addEventListener) {
    doc.addEventListener('visibilitychange', function () {
      if (doc.hidden) { lookId = null; releaseAll(); }
    });
  }
  window.addEventListener('blur', releaseAll);
  if (window.requestAnimationFrame) window.requestAnimationFrame(frame);

  watchStatus();

  // Exposed for the headless verifier (android/tools/verify-web-bundle.mjs) and
  // for debugging from a WebView console.
  window.SPAndroidPad = {
    pad: pad,
    offline: offline,
    backend: backend,
    press: press,
    release: release,
    releaseAll: releaseAll,
    startOnce: startOnce
  };
})();
